import gsap from 'gsap';

import CabinetPackage, { CabinetScaleOverrides, ComponentVisibility, IAutoPlayText, ICabinetButtonTextConfig, ICabinetMessage, IStake, IVisibility } from '@game-studio/cabinet';
import { RESULT_CODES } from '@game-studio/server-comms';
import { deepMerge } from '@game-studio/utilities';

import { SettingsEventEmitter } from '@game-studio/settings';
import { gameConfig } from '../models/config-model';
import { OverlaysEventEmitter, useCompanionState } from '..';
import { inversifyContainer } from '../inversify/container';
import { demoState } from '../models/demo-model';
import { bootstrapErrorModel } from '../models/error-model';
import { loggingModel } from '../models/logging';
import { sessionDataModel } from '../models/session-data';
import { userModel } from '../models/user';
import { userPreferences } from '../models/user-preferences';
import { device } from '../services/device';
import { endGameValidator } from '../services/end-game-verification';
import { environment } from '../services/environment';
import { eventEmitter } from '../services/event-emitter';
import { queryStringParams } from '../services/query-string';
import { buildDynamicString, delay, getLocaleString } from '../services/utilities';
import { CabinetButtonStringOption, IBaseServerResponse } from '../types';
export type CabinetActionState = 'buy' | 'reveal' | 'stop' | 'auto-buy' | 'disabled' | 'bonus';

export interface ICabinetOptions {
    revealMode?: {
        canSingleReveal?: boolean | { value: boolean; buttonText: CabinetButtonStringOption | ICabinetButtonTextConfig; revealHoldDelay?: number };
        canRevealAll?: boolean | { value: boolean; buttonTextureName: string };
        canStopRevealAll?: boolean | { value: boolean; buttonTextureName: string };
    };
    freeGame?: {
        startTextureName: string;
        progressTextureName: string;
        hasProgressCounter: boolean;
    };
    postGameDurationMS?: number | IPostGameDuration;
    minimumReactivationTimeMS?: number;
    /** @deprecated Cabinet no longer supports Game Info Visibility. It's now always visible. */
    visibility?: IVisibility;
    /** @deprecated Cabinet no longer supports the Clock. It has been moved to session overlays. */
    clockVisibility?: ComponentVisibility;
    audio?: {
        stakeChangeAsset?: string;
        purchaseAsset?: string;
    };
    /** @deprecated Cabinet no longer supports Scale Overrides. */
    scaleOverrides?: CabinetScaleOverrides;
    disableFloatingLayout?: boolean;
    /**
     * Opts in to responsive button scaling in portrait floating layout.
     * Omitting this option disables the feature entirely (opt-in).
     */
    floatingLayoutOptions?: IFloatingLayoutOptions;
}

export interface IFloatingLayoutOptions {
    /** Fraction of game width used to size the action button. Default: 0.12 (12%). */
    screenWidthPercentage?: number;
    /** Gap between the action button bottom and the cabinet bar, as a multiple of button height. Default: 0.3. */
    gapMultiplier?: number;
}

export interface IPostGameDuration {
    duration: number;
    preventAccidentalBuyIn: boolean;
    winOnly: boolean;
}

export interface ICabinetMessageEx {
    text: ICabinetMessage | string;
    options?: {
        amount?: string;
        instant?: boolean;
    };
}

export class BaseCabinet extends CabinetPackage {

    protected startTime: number | undefined;

    protected _delayedMessageTween: gsap.core.Tween = gsap.delayedCall(0, () => undefined);
    protected _noWinMessageResetDelayS: number = 2;
    // CabinetPackage's holdSpinnerDuration setter has no getter, so cache the value here to read it back
    protected _currentHoldDurationS: number = 1.0;
    // readonly to enforce only changing via the setter
    protected readonly _actionButtonState: CabinetActionState = 'buy';

    // Reveal Feature
    protected _canSingleReveal: boolean = false;
    protected _canRevealAll: boolean = false;
    protected _canStopRevealAll: boolean = false;
    protected _revealAllHoldDelayS: number = 0.6;
    protected _singleRevealButton: ICabinetButtonTextConfig = inversifyContainer.cabinetConfig.buttonTexts.reveal;
    protected _revealAllButton: string = 'reveal-all-button';
    protected _stopButton: string = 'stop-button';

    // Action button Hold Feature
    protected _actionButtonTimeout: number | undefined;
    protected _actionButtonHoldTimeout: number | undefined;
    protected _canProcessNextActionButtonClick: boolean = true;
    protected _delayBeforeStartingHoldMS: number = 250;

    // Minimum reactivation time to prevent buy-in attempts under X time apart
    protected _awaitingMinimumReactivationTimeout: boolean = false;
    protected _minimumReactivationTimeMS: number = 0;
    protected _reactivationTimeout: number | undefined;

    // Post game delay to prevent spam buying
    protected _awaitingPostGameTimeout: boolean = false;
    protected _postGameTimeAmountDurationMS: number = 0;
    protected _postGameTimout: number | undefined;
    protected _preventAccidentalBuyIn: boolean = true;
    protected _postGameTimeoutWinOnly: boolean = true;

    // Bonus Feature
    protected _bonusStateName: string = 'none';

    // Auto Buy Feature
    protected _autoBuyTimeout: number | undefined;
    protected _autoBuyPopupDelayS: number = 1.0;
    protected _maxAutoBuys: number = 0;
    protected _autoBuysRemaining: number = 0;
    protected _isAutoBuyEnabled: boolean = false;
    protected _isBetweenAutoBuys: boolean = false;
    protected _autoBuyStopButton: string = 'stop-with-count';
    public get isAutoBuying(): boolean {
        return this._actionButtonState === 'auto-buy';
    }

    // Audio asset names
    protected _stakeChangeAssetName: string = 'stake-change';
    protected _purchaseAssetName: string = 'purchase';

    // Tracks whether the game activated the nudge this session (i.e. emitted true for a new player)
    private isHTPNudgeActivated: boolean = false;
    // Tracks whether HTP hid the nudge so it can be restored when HTP closes
    private shouldRestoreOnHTPClose: boolean = false;
    // Tracks whether the autoplay popup hid the nudge so it can be restored when cancelled
    private shouldRestoreOnAutoPlayCancel: boolean = false;

    protected _isFloatingLayoutEnabled: boolean;

    /** The Autobuy feature is allowed if enabled and not in FreePlay mode */
    public get shouldAllowAutoBuy(): boolean {
        return this._isAutoBuyEnabled && !this.inFreePlay;
    }

    public get wasHTPNudgeDisplayedThisSession(): boolean {
        return this.isHTPNudgeActivated;
    }

    private readonly gameInfoVisibility: IVisibility = {
        portrait: true,
        landscape: true
    };

    /**
     * State manager for the action button controling how it looks when entering each state
     * (texture, enabled, purchaseText, holdSpinnerDuration, etc...)
     *
     * Note: 'bonus' state doesn't do anything as this should be fully configured by the game
     */
    protected set actionButtonState(newState: CabinetActionState) {
        // casting to ignore the readonly
        (this._actionButtonState as CabinetActionState) = newState;
        switch (newState) {
            case 'buy':
                this.setToBuyState();
                break;
            case 'reveal':
                this.enablePurchaseButton();
                this.hidePurchaseText();
                this.holdSpinnerDuration = this._revealAllHoldDelayS;
                if (this._canSingleReveal) {
                    this.updatePurchaseMainText(this._singleRevealButton);
                    break;
                }

                this.updatePurchaseMainText(inversifyContainer.cabinetConfig.buttonTexts.revealAll);
                break;
            case 'stop':

                this.updatePurchaseMainText(inversifyContainer.cabinetConfig.buttonTexts.stop);
                break;
            case 'auto-buy':
                this.enablePurchaseButton();
                this.updatePurchaseMainText(inversifyContainer.cabinetConfig.buttonTexts.autoBuyStop);
                this.animateStakeText(this._autoBuysRemaining.toString());
                break;
            case 'disabled':
                this.disablePurchaseButton();
                break;
            case 'bonus':
                break;
            default:
                console.error('Invalid State passed to buttonState');
                this.disablePurchaseButton();
                break;
        }
    }

    constructor(gameOptions?: ICabinetOptions) {
        const options: ICabinetOptions = deepMerge({}, inversifyContainer.cabinetBaseOptions, gameOptions ?? {});
        
        super(device, userPreferences, inversifyContainer.cabinetConfig, queryStringParams.locale);

        this._isFloatingLayoutEnabled = !(options.disableFloatingLayout) ?? true;
        this._layoutState = this._isFloatingLayoutEnabled ? 'floating' : 'anchored';

        if (options.floatingLayoutOptions) {
            this._isScalingLayoutEnabled = true;
            if (options.floatingLayoutOptions.screenWidthPercentage !== undefined) {
                this._scalingLayoutWidthFraction = options.floatingLayoutOptions.screenWidthPercentage;
            }
            if (options.floatingLayoutOptions.gapMultiplier !== undefined) {
                this._scalingLayoutGapMultiplier = options.floatingLayoutOptions.gapMultiplier;
            }
        } else {
            this._isScalingLayoutEnabled = false;
        }

        if (gameConfig.features.maxAutoBuys > 0) {
            this._isAutoBuyEnabled = true;
            this._maxAutoBuys = gameConfig.features.maxAutoBuys;
        }

        if (options?.postGameDurationMS) {
            if (typeof options?.postGameDurationMS === 'number') {
                this._postGameTimeAmountDurationMS = options.postGameDurationMS;
            } else {
                this._postGameTimeAmountDurationMS = options.postGameDurationMS.duration;
                this._preventAccidentalBuyIn = options.postGameDurationMS.preventAccidentalBuyIn;
                this._postGameTimeoutWinOnly = options.postGameDurationMS.winOnly;
            }
        }

        if (options?.minimumReactivationTimeMS) {
            this._minimumReactivationTimeMS = options.minimumReactivationTimeMS;
        }

        if (options?.visibility) {
            this.gameInfoVisibility = options.visibility;
        }

        if (options?.revealMode?.canSingleReveal) {
            if (typeof options.revealMode.canSingleReveal === 'boolean') {
                this._canSingleReveal = options.revealMode.canSingleReveal;
            } else {
                this._canSingleReveal = options.revealMode.canSingleReveal.value;

                if (typeof options.revealMode.canSingleReveal.buttonText === 'object') {
                    this._singleRevealButton = options.revealMode.canSingleReveal.buttonText;
                } else {
                    this._singleRevealButton = inversifyContainer.cabinetConfig.buttonTexts[options.revealMode.canSingleReveal.buttonText];
                }

                if (options?.revealMode?.canSingleReveal?.revealHoldDelay) {
                    this._revealAllHoldDelayS = options.revealMode.canSingleReveal.revealHoldDelay;
                }
            }
        }

        if (options?.revealMode?.canRevealAll) {
            if (typeof options.revealMode.canRevealAll === 'boolean') {
                this._canRevealAll = options.revealMode.canRevealAll;
            } else {
                this._canRevealAll = options.revealMode.canRevealAll.value;
                this._revealAllButton = options.revealMode.canRevealAll.buttonTextureName;
            }
        }

        if (options?.revealMode?.canStopRevealAll) {
            if (typeof options.revealMode.canStopRevealAll === 'boolean') {
                this._canStopRevealAll = options.revealMode.canStopRevealAll;
            } else {
                this._canStopRevealAll = options.revealMode.canStopRevealAll.value;
                this._stopButton = options.revealMode.canStopRevealAll.buttonTextureName;
            }
        }

        if (options?.audio) {
            this._stakeChangeAssetName = options.audio.stakeChangeAsset || 'stake-change';
            this._purchaseAssetName = options.audio.purchaseAsset || 'purchase';
        }
    }

    /**
     * Loads standard cabinet assets then setup initial state
     * @listens 'GLOBAL_SUSPEND'
     */
    public async init(): Promise<void> {
        const width = device.gameWidth;
        const height = device.gameHeight;
        return super.init(inversifyContainer.strings.cabinet, width, height)
            .then(() => {
                this.updateStyles();

                this.gameInfoComponentVisibility = this.gameInfoVisibility;
                this.setCabinetMessageEx(inversifyContainer.strings.cabinet.default);

                this.setCurrentBalance(inversifyContainer.currencyFormatter.precise(userModel.visibleBalance.startBalance));
                this.animateStakeText(inversifyContainer.stake.formattedStake);

                this.updateStakeButtons();
                this.updateAutoPlayText();

                this.updatePurchaseMainText(inversifyContainer.cabinetConfig.buttonTexts.buy);
                // Sizes the cabinet background before positioning the autoplay popup off it, otherwise it uses the unsized background dimensions
                this.handleOrientationChange();

                if (bootstrapErrorModel.errorState === 'UNHANDLED' || !inversifyContainer.gameServer.canPurchase) {
                    this.disableAll();
                }

                const hasFreePlays = inversifyContainer.gameModel.playMode === 'FreePlay' && inversifyContainer.gameModel.isComplete === false;

                if (gameConfig.supportsFreeplays && (userModel.freePlayBalance !== 0 || hasFreePlays)) {
                    this.enterFreePlay();
                    eventEmitter.emit('POPUP_HIDE_SESSION');
                }

                this.holdSpinnerDuration = this._currentHoldDurationS = this._autoBuyPopupDelayS;

                eventEmitter.on('GLOBAL_SUSPEND', this.onGameSuspended, this);
                eventEmitter.on('GLOBAL_WALLET_UPDATED', this.onWalletUpdated, this);
                eventEmitter.on('GAME_SWIPE_TO_BUY', this.onSwipeToBuy, this);
                eventEmitter.on('COMPANION_PANEL_CHANGED', this.updatePurchaseLayout, this);
                eventEmitter.on('POPUP_TOGGLE_HTP_NUDGE_POPUP', this.onActivateHTPNudge, this);
                eventEmitter.on('POPUP_HTP_VISIBILITY_CHANGED', this.onHTPVisibilityChanged, this);

                return;
            });
    }

    public enterFreePlay(): void {
        if (gameConfig.supportsFreeplays) {
            this.setFreePlayBalance(userModel.freePlayBalance);
            this.setCabinetMessageEx(inversifyContainer.strings.cabinet.freePlay);
            super.enterFreePlay(inversifyContainer.cabinetConfig.buttonTexts.freePlay);
            eventEmitter.emit('CABINET_STAKE_CHANGE');
        }
    }

    public leaveFreePlay(): void {
        if (queryStringParams.locale === 'it-it') {
            userModel.hideBalance = true;
        }

        this.clearInFreePlay();
        this.enterRealMoneyMode();
    }

    public enterDemoMode(): void {
        this.displayDemoBalance();
        eventEmitter.emit('CABINET_STAKE_CHANGE');
    }

    public leaveDemoMode(): void {
        this.enterRealMoneyMode();
    }

    public enterRealMoneyMode(): void {
        this.setCabinetMessageEx(inversifyContainer.strings.cabinet.default);
        this.setCurrentBalance(inversifyContainer.currencyFormatter.precise(userModel.visibleBalance.endBalance));
        this.actionButtonState = 'buy';
        eventEmitter.emit('CABINET_STAKE_CHANGE');
        this.updateStakeButtons();
        if (inversifyContainer.gameSettings.stakeOptions.length === 0) {
            inversifyContainer.gameServer.emit('ON_INVALID_STAKE');
            inversifyContainer.cabinet.disablePurchaseButton();
            inversifyContainer.cabinet.disableStakeButtons();
        }
    }

    /** Overloded to update the gameInfoVisibility */
    public handleOrientationChange(): void {
        const width = device.gameWidth;
        const height = device.gameHeight;

        this.updatePurchaseLayout();

        super.handleOrientationChange(width, height);
    }

    /**
     * Function to call once the game has fully finished, after any bonuses are played through.
     * Displays the final result, performs any validation / logging and setsup the cabinet to buy into the next game (autoBuys in if autoBuying)
     */
    public async endGame(): Promise<void> {
        if (!this.isAutoBuying) {
            this.actionButtonState = 'disabled';
        }
        endGameValidator.endGame();

        if (this.startTime !== undefined) {
            loggingModel.gameTime = Number(((Date.now() - this.startTime) / 1000).toFixed(2));
        }

        this.setActivePanelLog();

        loggingModel.logEndGameMetrics();

        inversifyContainer.gameModel.isInProgress = false;
        eventEmitter.emit('GAME_COMPLETE');
        //TODO: reimplement this when SE session alerts get merged into shell
        // inversifyContainer.frameConnection.operator.updateGameInPlay({ gameInPlay: false });

        const payout = inversifyContainer.gameModel.payout;

        if (payout > 0) {
            this.setCabinetWinMessage(inversifyContainer.gameModel.hasBonus);

            if (payout >= inversifyContainer.stake.currentStake * gameConfig.bigWinStakeMultiplier) {
                await inversifyContainer.bigWin.showBigWin();
            }
        } else {
            this.setCabinetLoseMessage();
        }

        if (this.inFreePlay) {
            if (userModel.freePlayBalance < 1) {
                this.setFreePlayBalance(0);
                eventEmitter.emit('GLOBAL_FREE_PLAY_ENDED', payout, inversifyContainer.currencyFormatter.precise(payout));
                return;
            } else {
                this.setFreePlayBalance(userModel.freePlayBalance);
            }
        } else if (payout > 0) {
            this.setCurrentBalance(inversifyContainer.currencyFormatter.precise(userModel.visibleBalance.endBalance));
            inversifyContainer.frameConnection.operator.onSessionInfo({
                userId: userModel.userId,
                balance: userModel.totalBalance.endBalance,
                realBalance: 0, // TODO this is a value used by sisal, will need to be added once the arcade games are on the sisal network
                bonusBalance: 0, // TODO this is a value used by sisal, will need to be added once the arcade games are on the sisal network
                gameName: queryStringParams.currentSkin,
                version: gameConfig.version,
                sessionTime: 0, // TODO: leaving this as 0 for now as unused, may need adding later
                locale: getLocaleString()
            });
        }

        // Check for freeplays after bonus round and enter freeplay if new freeplays have been awarded during a bonus round.
        if (userModel.freePlayBalance > 0 && gameConfig.supportsFreeplays && !this.inFreePlay) {
            eventEmitter.emit('GLOBAL_FREE_PLAY_EARNED', userModel.freePlayBalance);
            this.resetGameAfterBonus();
            this.enterFreePlay();
            return;
        }

        if (this.isAutoBuying) {
            if (this._autoBuysRemaining > 0 && payout < (inversifyContainer.stake.currentStake * 10) && inversifyContainer.gameModel.isComplete) {
                this._isBetweenAutoBuys = true;
                const timeBetweenGames = payout > 0 ? 4000 : 2000;

                this._autoBuyTimeout = window.setTimeout(() => {
                    this._isBetweenAutoBuys = false;
                    this.sendBeginRequest();
                }, timeBetweenGames);
            } else {
                this.actionButtonState = 'buy';
                this.updateStakeButtons();
            }
        } else {
            this.resetGameAfterBonus();
        }
    }

    public resetGameAfterBonus(): void {
        this.startPostGameTimeout();
        this.actionButtonState = 'buy';
        this.updateStakeButtons();
    }

    /**
     * formats the current stake to a currency string before returning as IStake
     */
    public getStake(): IStake {
        return {
            stake: inversifyContainer.stake.formattedStake,
            stakeAsPennies: inversifyContainer.stake.currentStake
        };
    }

    /** enables/disables the stake buttons dependant on the currentStake value */
    public updateStakeButtons(): void {
        if (inversifyContainer.stake.currentStake >= inversifyContainer.stake.highestStake) {
            this.disablePlusButton();
        } else {
            this.enablePlusButton();
        }

        if (inversifyContainer.stake.currentStake <= inversifyContainer.stake.lowestStake) {
            this.disableMinusButton();
        } else {
            this.enableMinusButton();
        }
    }

    /**
     * Enters the cabinet bonus state. 
     * @param stateName Name of the state being entered. Usually 'bonus'
     * @param buttonText Predefined string options to update main purchase text
     */
    public enterBonusState(stateName: string, buttonText: CabinetButtonStringOption): void
    /**
     * Enters the cabinet bonus state. 
     * @param stateName Name of the state being entered. Usually 'bonus'
     * @param textConfig Object or `container.cabinetConfig.buttonTexts.` to update main purchase text
     */
    public enterBonusState(stateName: string, textConfig: ICabinetButtonTextConfig): void
    public enterBonusState(stateName: string, ag2: CabinetButtonStringOption | ICabinetButtonTextConfig): void {
        if (typeof ag2 === 'object') {
            super.updatePurchaseMainText(ag2);
        } else {
            super.updatePurchaseMainText(inversifyContainer.cabinetConfig.buttonTexts[ag2]);
        }
        this._bonusStateName = stateName;
        this.actionButtonState = 'bonus';
    }

    public exitBonusState(): void {
        this._bonusStateName = 'none';
        this.actionButtonState = 'buy';
    }

    public onBonusTriggered(updateMessage: boolean = true): void {
        if (updateMessage) {
            this.setBonusMessage();
        }
        this.cancelAutoPlay();
    }

    /**
     * Displays the bonus.entering string, returns a promise to allow for waiting a supplied time before continuing
     * @param delayTimeMS time in milliseconds to wait before resolving the returned promise
     */
    public async setBonusMessage(delayTimeMS: number = 1500): Promise<void> {
        if (inversifyContainer.strings.cabinet.bonus === undefined) {
            console.error('String Error: Called Cabinet.setBonusMessage() with no bonus strings defined in the strings file');
            this.setCabinetMessageEx('error!');
            return;
        }

        this.setCabinetMessageEx(inversifyContainer.strings.cabinet.bonus.entering);
        this.flashMessage();
        await delay(delayTimeMS);
    }

    /**
     * Displays the cabinet.win (or cabinet.return if payout < stake) string with the value of `gameModel.payout`, message only flashes if payout > stake
     * @param showAsBonusWin {boolean} if true displays cabinet.bonus.win instead, defaults to false
     */
    public setCabinetWinMessage(showAsBonusWin: boolean = false): void {
        let message = inversifyContainer.gameModel.payout > inversifyContainer.stake.currentStake ? inversifyContainer.strings.cabinet.win : inversifyContainer.strings.cabinet.return;

        if (showAsBonusWin) {
            if (inversifyContainer.strings.cabinet.bonus !== undefined) {
                message = inversifyContainer.strings.cabinet.bonus.win;
            } else {
                console.error('String Error: Called Cabinet.setCabinetWinMessage(true) with no bonus strings defined in the strings file');
                this.setCabinetMessageEx('error!');
            }
        }

        const winValue = inversifyContainer.currencyFormatter.precise(inversifyContainer.gameModel.payout);
        this.setCabinetMessageEx(message, { amount: winValue });
        this.flashPrize();
    }

    /** Displays the cabinet.noWin string for 2 seconds then animates to the cabinet.default string */
    public setCabinetLoseMessage(): void {
        this.setCabinetMessageEx(inversifyContainer.strings.cabinet.noWin);
        this._delayedMessageTween = gsap.delayedCall(this._noWinMessageResetDelayS, () => {
            if (this.inFreePlay) {
                this.setCabinetMessageEx(inversifyContainer.strings.cabinet.freePlay);
                return;
            }

            this.setCabinetMessageEx(inversifyContainer.strings.cabinet.default);
        });
    }

    /** Overloaded to kill any delayedMessageTweens before changing the message */
    public setCabinetMessage(message: ICabinetMessage, instant?: boolean): void {
        this._delayedMessageTween.kill();
        super.setCabinetMessage(message, instant);
    }

    /**
     * Accepts types of ICabinetMessage, string or an array of them both which it converts to ICabinetMessage to pass to setCabinetMessage.
     * If an array is passed it will animate the first item, then doe each of the others `options.delayTimeS` seconds apart
     * @param message The message data to display
     * @param options can pass an `amount` or `instant` flag for single messges or `delayTimeS` is passing an array of messages
     */
    public setCabinetMessageEx(message: ICabinetMessage | string | undefined, options?: { amount?: string, instant?: boolean }): void;
    public setCabinetMessageEx(message: ICabinetMessage | string | Array<ICabinetMessage | string> | undefined, options?: { delayTimeS?: number }): void;
    public setCabinetMessageEx(message: ICabinetMessage | string | Array<ICabinetMessage | string> | undefined, options?: { amount?: string, instant?: boolean, delayTimeS?: number }): void {
        let messages: Array<ICabinetMessage | string>;
        if (Array.isArray(message)) {
            if (message === undefined || message.length < 1 || message[0] === undefined || message[0] === '') { return; }
            messages = [...message];
        } else {
            if (message === undefined || message === '') { return; }
            messages = [message];
        }

        let item = messages.shift();
        if (!item) { return; }
        if (typeof item === 'string') {
            item = {
                portrait: item,
                landscape: item,
                amount: options?.amount || undefined
            };
        }

        this.setCabinetMessage(item, false);

        if (messages.length > 0) {
            const delayTime = options?.delayTimeS || 2;
            this._delayedMessageTween = gsap.delayedCall(delayTime, () => this.setCabinetMessageEx(messages, { delayTimeS: delayTime }));
        }
    }

    /**
     * An Expanded setCabinetMessageEx which allows for passing an amount or instant flag for each message in the list
     * @param message {ICabinetMessageEx} The message to display along with any options for it, can be an array and each message will display after `delayTimeS` seconds
     * @param delayTimeS {number} time in seconds between each message in the message list, does nothing if only 1 message is passed
     */
    public setCabinetMessageEx2(message: ICabinetMessageEx | ICabinetMessageEx[], delayTimeS: number = 1.5): void {
        let messages: ICabinetMessageEx[];
        if (Array.isArray(message)) {
            if (message.length < 1 || message[0].text === undefined || message[0].text === '') { return; }
            messages = [...message];
        } else {
            if (message.text === undefined || message.text === '') { return; }
            messages = [message];
        }

        const item = messages.shift();
        if (!item) { return; }
        if (typeof item.text === 'string') {
            item.text = {
                portrait: item.text,
                landscape: item.text,
                amount: item.options?.amount
            };
        } else {
            item.text.amount = item.options?.amount;
        }

        this.setCabinetMessage(item.text, item.options?.instant);

        if (messages.length > 0) {
            this._delayedMessageTween = gsap.delayedCall(delayTimeS, () => this.setCabinetMessageEx2(messages));
        }
    }

    /**
     * @fires 'CABINET_START_REVEAL_ALL'
     */
    public startRevealAll(): void {
        const message = inversifyContainer.strings.cabinet.revealingAll;
        this.setCabinetMessageEx(message);

        if (this._canStopRevealAll) {
            this.actionButtonState = 'stop';
        } else {
            this.actionButtonState = 'disabled';
        }
        loggingModel.autoPlayUsed = true;

        eventEmitter.emit('CABINET_START_REVEAL_ALL');
    }

    /**
     * Used if you don't want the buy button to be re-enabled after a game,
     * for example if some validation fails
     */
    public cancelPostGameTimeout(): void {
        this._postGameTimeAmountDurationMS = 0;
        window.clearTimeout(this._postGameTimout);
    }

    /**
     * @fires 'CABINET_STOP_REVEAL_ALL'
     */
    public stopRevealAll(): void {
        this.actionButtonState = 'reveal';
        eventEmitter.emit('CABINET_STOP_REVEAL_ALL');
    }

    /**
     * override the enable purchase button to prevent enabling the purchase button if a bootstrap error has occured
     */
    public enablePurchaseButton(): void {
        if (bootstrapErrorModel.errorState === 'UNHANDLED' || !inversifyContainer.gameServer.canPurchase) {
            return;
        }
        super.enablePurchaseButton();
    }

    /**
     * override set current balance for demo mode logic
     */
    public setCurrentBalance(amount: string): void {
        if (demoState.isDemoMode) {
            this.displayDemoBalance();
        } else {
            const value = userModel.hideBalance ? '' : amount;
            super.setCurrentBalance(value);
        }
    }

    /**
     * To be called when attempting a failable action such as purchase with requires a network response.
     * disables the action button without shrinking it and shows a delayed spinner while the action processes.
     * 
     * onActionSuccess should be called once the action is successful
     */
    public onActionAttempt(): void {
        this.disablePurchaseButton({ shouldScale: false });
        this.showLoadingSpinner(this.loadingSpinnerDelay);
    }

    /**
     * To be called once an action attempted in onActionAttempt is successful, hides the spinner and shinks the action button
     */
    public onActionSuccess(): void {
        this.disablePurchaseButton();
        this.hideLoadingSpinner();
    }

    public enableFloatingLayout(): void {
        this._isFloatingLayoutEnabled = true;
        this.handleOrientationChange();
    }

    public disableFloatingLayout(): void {
        this._isFloatingLayoutEnabled = false;
        this.handleOrientationChange();
    }

    protected updatePurchaseLayout(): void {
        const isCompanionPanelHidden = useCompanionState().activePanel.value === null;
        const isMobilePortrait = device.orientation.isPortrait && device.type.isMobile;
        const isSubGame = queryStringParams.isSubGame;
        const shouldUseFloatingLayout = this._isFloatingLayoutEnabled && isMobilePortrait && isCompanionPanelHidden && !isSubGame;
        const purchaseLayout = shouldUseFloatingLayout ? 'floating' : 'anchored';

        super.updatePurchaseLayout(purchaseLayout);
    }

    protected displayDemoBalance(): void {
        const isAuthenticatedDemoMode = demoState.isAuthenticatedDemo;

        if (isAuthenticatedDemoMode) {
            const playString = demoState.demoGamesRemaining === 1 ? inversifyContainer.strings.overlays.sessionData.demoPlay : inversifyContainer.strings.overlays.sessionData.demoPlays;

            super.setCurrentBalance(`${demoState.demoGamesRemaining} ${playString}`);
        } else {
            super.setUnAuthDemoBalance(inversifyContainer.strings.cabinet.balanceDemoLabel);
        }
    }

    /**
     * @fires 'SettingsEventEmitter.show' - on click
     * @fires 'POPUP_TOGGLE_GAME_INFO' - on hold for more than 1 second
     */
    protected onSettingsButtonClick(): void {
        if (environment !== 'live' && ((Date.now() - this.settingsTouchStartTime) > 1000)) {
            eventEmitter.emit('POPUP_TOGGLE_DEBUG_OVERLAY', true);
        } else {
            SettingsEventEmitter.emit('toggle');
        }
    }

    /**
     * @fires 'CABINET_STAKE_CHANGE'
     */
    protected onIncreaseStakeClick(): IStake {
        inversifyContainer.soundManager.sfx.play(this._stakeChangeAssetName);

        this.enableMinusButton();
        inversifyContainer.stake.increaseStake();
        eventEmitter.emit('CABINET_STAKE_CHANGE');

        if (inversifyContainer.stake.currentStake >= inversifyContainer.stake.highestStake) {
            this.disablePlusButton();
        }

        this.setMaxWinText();
        if (gameConfig.features.maxAutoBuys > 0) {
            this.updateAutoPlayText();
        }

        return { stake: inversifyContainer.stake.formattedStake, stakeAsPennies: inversifyContainer.stake.currentStake };
    }

    /**
     * @fires 'CABINET_STAKE_CHANGE'
     */
    protected onDecreaseStakeClick(): IStake {
        inversifyContainer.soundManager.sfx.play(this._stakeChangeAssetName);

        this.enablePlusButton();
        inversifyContainer.stake.decreaseStake();
        eventEmitter.emit('CABINET_STAKE_CHANGE');

        if (inversifyContainer.stake.currentStake <= inversifyContainer.stake.lowestStake) {
            this.disableMinusButton();
        }

        this.setMaxWinText();
        if (gameConfig.features.maxAutoBuys > 0) {
            this.updateAutoPlayText();
        }

        return { stake: inversifyContainer.stake.formattedStake, stakeAsPennies: inversifyContainer.stake.currentStake };
    }

    /**
     * @fires 'POPUP_TOGGLE_DEBUG_OVERLAY' - on click
     */
    protected onGameInfoClick(): void {
        SettingsEventEmitter.emit('hide');
        eventEmitter.emit('POPUP_TOGGLE_GAME_INFO', undefined, 'cabinet');
    }

    /**
     * Triggers on pointer-up, after onHoldEnd
     * @fires 'POPUP_TOGGLE_GAME_INFO', with the value of false
     */
    protected onActionButtonClick(): void {
        eventEmitter.emit('POPUP_TOGGLE_GAME_INFO', false, 'cabinet');

        if (this._awaitingPostGameTimeout) {
            this.startPostGameTimeout();
            return;
        }

        if (!this._canProcessNextActionButtonClick) {
            this._canProcessNextActionButtonClick = true;
            return;
        }
        this.hideAutoPlayPopup();

        switch (this._actionButtonState) {
            case ('buy'):
                if (!this.inFreePlay && (inversifyContainer.stake.currentStake < inversifyContainer.stake.lowestStake || inversifyContainer.stake.currentStake > inversifyContainer.stake.highestStake)) {
                    OverlaysEventEmitter.emit('showToast', '', inversifyContainer.errorStrings[RESULT_CODES.BET_HIGHER_THAN_LIMIT]);
                    return;
                }
                this.sendBeginRequest();
                break;
            case ('reveal'):
                if (this._canSingleReveal) {
                    loggingModel.updatePlayStyle('tap');
                    this.revealNext();
                    break;
                }
                this.startRevealAll();
                break;
            case ('stop'):
                this.stopRevealAll();
                break;
            case ('bonus'):
                eventEmitter.emit('CABINET_BONUS_ACTION', this._bonusStateName);
                break;
            case ('auto-buy'):
                this.cancelAutoPlay();
                break;
            default:
                console.warn(`onActionButtonClick with invalid state: ${this._actionButtonState}`);
                break;
        }
    }

    protected onActionButtonHold(): void {
        if (this._awaitingPostGameTimeout) {
            return;
        }

        if (!this.isAutoBuying) {
            if ((this._actionButtonState === 'reveal' && this._canSingleReveal && this._canRevealAll) || (this._actionButtonState === 'buy' && this.shouldAllowAutoBuy)) {
                window.clearTimeout(this._actionButtonTimeout);
                window.clearTimeout(this._actionButtonHoldTimeout);

                this._actionButtonTimeout = window.setTimeout(() => {
                    this.showActionHoldSpinner();
                    this._canProcessNextActionButtonClick = false;

                    this._actionButtonHoldTimeout = window.setTimeout(() => {
                        this.hideActionHoldSpinner();
                        if (this._actionButtonState === 'reveal' && this._canRevealAll) {
                            loggingModel.updatePlayStyle('hold');
                            this.startRevealAll();
                        } else if (this._actionButtonState === 'buy' && this.shouldAllowAutoBuy && sessionDataModel.validateSession()) {
                            this.updateAutoPlayText();
                            if (this.htpNudgeState === 'shown') {
                                this.hideHTPNudge();
                                this.shouldRestoreOnAutoPlayCancel = true;
                            } else {
                                this.shouldRestoreOnAutoPlayCancel = false;
                            }
                            this.showAutoPlayPopup();
                        }
                    }, 1000 * this.holdSpinnerDuration);
                }, this._delayBeforeStartingHoldMS);
            }
        }
    }

    /**
     * Fires when releasing the ActionButton
     * Before onActionButtonClick happens
     */
    protected onActionButtonHoldEnd(): void {
        window.clearTimeout(this._actionButtonTimeout);
        window.clearTimeout(this._actionButtonHoldTimeout);

        this.hideActionHoldSpinner();
    }

    protected onActionButtonHoldEndOutside(): void {
        this._canProcessNextActionButtonClick = true;
        this.onActionButtonHoldEnd();
    }

    protected onSwipeToBuy(): void {
        if (this._actionButtonState === 'buy') {
            this.onActionButtonClick();
        }
    }

    /**
     * @fires 'CABINET_BEGIN_SENT' - when a request is sent to the server
     * @fires 'CABINET_BEGIN' - after receiving and processing a successful response
     * @fires 'CABINET_STAKE_CHANGE' - on recieving a BET_HIGHER_THAN_LIMIT errorResponse from the server
     */
    protected async sendBeginRequest(): Promise<void> {
        if (!sessionDataModel.validateSession()) { return; }

        this.disableStakeButtons();
        this.onActionAttempt();
        try {
            eventEmitter.emit('CABINET_BEGIN_SENT');
            const response = await inversifyContainer.gameServer.beginRequest(gameConfig.engineSkinName, this.inFreePlay);
            inversifyContainer.soundManager.sfx.play(this._purchaseAssetName);
            this.onActionSuccess();

            this.startReactivationTimeout();

            userModel.setData(response.PlayerData, 'Begin', false, response.SessionStatus);
            inversifyContainer.gameModel.setData(response);

            inversifyContainer.stake.updateStakes(response.GameSettings);
            this.startTime = Date.now();
            if (this.inFreePlay && !demoState.isDemoMode) {
                this.setFreePlayBalance(userModel.freePlayBalance);
            } else {
                this.setCurrentBalance(inversifyContainer.currencyFormatter.precise(userModel.visibleBalance.startBalance));
            }
            if (this.isAutoBuying) {
                this._autoBuysRemaining--;
                this.actionButtonState = 'auto-buy';
            } else if (this._canSingleReveal) {
                this.actionButtonState = 'reveal';
            } else if (this._canRevealAll) {
                this.actionButtonState = 'reveal';
            } else {
                this.actionButtonState = 'disabled';
            }
            this.setCabinetMessageEx(inversifyContainer.strings.cabinet.boughtIn);

            // Permanently dismiss the nudge after purchase.
            this.dismissHTPNudge();

            inversifyContainer.gameModel.isInProgress = true;

            sessionDataModel.setData(response);
            eventEmitter.emit('GAME_BEGIN', this.isAutoBuying);

            //TODO: reimplement this when SE session alerts get merged into shell
            // inversifyContainer.frameConnection.operator.updateGameInPlay({ gameInPlay: true });
        } catch (error) {
            if (!this.isPurchaseError(error)) {
                console.error(error);
                this.onPurchaseError(false);
                return;
            }
            // Handle various specific purchase events
            if (error.ResultCode?.ResultCode === RESULT_CODES.BET_HIGHER_THAN_LIMIT) {
                inversifyContainer.stake.updateStakes(error.GameSettings);
                this.setMaxWinText();
                eventEmitter.emit('CABINET_STAKE_CHANGE');
                this.onPurchaseError();
            } else if (error.ResultCode?.ResultCode === RESULT_CODES.USE_FREE_PLAY_FIRST) {
                this.onPurchaseError(false);
                if (gameConfig.supportsFreeplays) {
                    if (queryStringParams.locale === 'it-it') {
                        // Italian sessions require the user refresh the game to create a new free-plays session instead of switching between modes on the fly.
                        this.disableAll();
                        OverlaysEventEmitter.emit('showToast', '', inversifyContainer.strings.freePlay.refreshRequired);
                    } else {
                        userModel.updateFreePlayBalance(error.PlayerData?.FreePlayBalance ?? 1, 'Error');
                        eventEmitter.emit('GLOBAL_FREE_PLAY_EARNED', userModel.freePlayBalance);
                        if (userModel.freePlayBalance > 0) {
                            this.enterFreePlay();
                        }
                    }
                }
            } else if (error.ResultCode?.ResultCode === RESULT_CODES.NO_MORE_FREE_PLAY) {
                userModel.updateFreePlayBalance(0, 'Error');
                if (this.inFreePlay) {
                    this.setFreePlayBalance(0);
                    eventEmitter.emit('GLOBAL_FREE_PLAY_ENDED', 0, '0');
                }
                this.onPurchaseError();
            } else if (error.ResultCode?.ResultCode === RESULT_CODES.LOWER_STAKE_POSSIBLE || error.ResultCode?.ResultCode === RESULT_CODES.INTERNATIONAL_STAKE_EXCEEDS_SESSION_LIMIT) {
                eventEmitter.emit('GLOBAL_STAKE_ALERT', error.ResultCode.ResultCode);
                this.onPurchaseError();
            } else if (error.ResultCode?.ResultCode === RESULT_CODES.ACCOUNT_FAILURE) {
                eventEmitter.emit('GLOBAL_ACCOUNT_LOCKED');
            } else if (error.ResultCode?.ResultCode === RESULT_CODES.INTERNATIONAL_SESSION_ALREADY_ENDED) {
                sessionDataModel.setData(error);
                eventEmitter.emit('POPUP_SHOW_SESSION', {
                    freePlayBalance: userModel.freePlayBalance,
                    createSessionUrl: `${inversifyContainer.endPoints.urls[environment].game}createsession`,
                    subGameName: gameConfig.engineSkinName
                });
                this.onPurchaseError(false);
            } else {
                // Don't log errors for the following codes
                if (error.ResultCode?.ResultCode !== RESULT_CODES.INTERNATIONAL_NO_CURRENT_SESSION) {
                    console.error(error);
                }
                this.onPurchaseError(false);
            }
        }
    }

    /**
     * @fires 'CABINET_REVEAL_NEXT'
     */
    protected revealNext(): void {
        eventEmitter.emit('CABINET_REVEAL_NEXT');
    }

    protected onAutoPlayConfirmClick(): void {
        this._autoBuysRemaining = this._maxAutoBuys;
        this.actionButtonState = 'auto-buy';
        this.shouldRestoreOnAutoPlayCancel = false;

        this.sendBeginRequest();
    }

    protected onAutoPlayCancelClick(): void {
        if (this.shouldRestoreOnAutoPlayCancel) {
            this.showHTPNudge();
            this.shouldRestoreOnAutoPlayCancel = false;
        }
    }

    /** Flashes the message field when payout > currentStake */
    protected flashPrize(): void {
        if (inversifyContainer.gameModel.payout > inversifyContainer.stake.currentStake) {
            super.flashMessage();
        }
    }

    protected onPurchaseError(updateStake: boolean = true): void {
        this.hideLoadingSpinner();
        this.updateStakeButtons();
        this.actionButtonState = 'buy';
        this._canProcessNextActionButtonClick = true;
        if (!this.inFreePlay && updateStake) {
            this.animateStakeText(inversifyContainer.stake.formattedStake);
        }
        this._autoBuysRemaining = this._maxAutoBuys;
    }

    protected cancelAutoPlay(): void {
        if (!this.isAutoBuying) { return; }

        this.hideLoadingSpinner();
        this._autoBuysRemaining = 0;
        window.clearTimeout(this._autoBuyTimeout);

        if (this._isBetweenAutoBuys) {
            this._isBetweenAutoBuys = false;

            this.actionButtonState = 'buy';
            if (inversifyContainer.gameModel.isComplete && !inversifyContainer.gameModel.isInProgress) {
                this.updateStakeButtons();
            }
        } else {
            if (this._canSingleReveal || this._canRevealAll) {
                this.actionButtonState = 'reveal';
                if (this._canStopRevealAll) {
                    this.stopRevealAll();
                } else { this.disablePurchaseButton(); }
            } else {
                this.actionButtonState = 'disabled';
            }
        }
    }

    protected setMaxWinText(): void {
        const gameSettings = inversifyContainer.gameSettings;
        const maxWinMultiplier = gameSettings.maxWinStakeMultiplier;
        const maxWinValue = inversifyContainer.currencyFormatter.precise(inversifyContainer.stake.currentStake * maxWinMultiplier);

        this.setCabinetMessageEx(inversifyContainer.strings.cabinet.maxWin, { amount: maxWinValue });
    }

    private onGameSuspended(): void {
        if (!this._canProcessNextActionButtonClick) {
            this._canProcessNextActionButtonClick = true;
        }

        if (this.isAutoBuying) {
            this.cancelAutoPlay();
        }

        this.hideAutoPlayPopup();
    }

    private onWalletUpdated(): void {
        if (this.inFreePlay) {
            this.setFreePlayBalance(userModel.freePlayBalance);
        } else {
            this.setCurrentBalance(inversifyContainer.currencyFormatter.precise(userModel.visibleBalance.startBalance));
        }
    }

    /**
     * Handles POPUP_TOGGLE_HTP_NUDGE_POPUP.
     * Only used by the game on init to activate the nudge for new players (emits true).
     */
    private onActivateHTPNudge(visibility?: boolean | void): void {
        if (visibility !== true) { return; }
        if (this.htpNudgeState === 'permanently-disabled') { return; }

        if (!this.isHTPNudgeActivated) {
            // First and only time: game has confirmed this is a new player
            this.isHTPNudgeActivated = true;
            this.showHTPNudge();
        }
    }

    /**
     * Handles HTP_VISIBILITY_CHANGED — emitted by the HTP view only on genuine player
     * open/close interactions, not from POPUP_TOGGLE_GAME_INFO.
     * @param isOpen - true when HTP opened, false when HTP closed
     */
    private onHTPVisibilityChanged(isOpen: boolean): void {
        if (this.htpNudgeState === 'permanently-disabled') { return; }

        if (isOpen) {
            // HTP opened — hide the nudge if it was showing and remember to restore it
            if (this.htpNudgeState === 'shown') {
                this.hideHTPNudge();
                this.shouldRestoreOnHTPClose = true;
            } else {
                this.shouldRestoreOnHTPClose = false;
            }
        } else {
            // HTP closed — restore the nudge if it was hidden by HTP opening
            if (this.shouldRestoreOnHTPClose) {
                this.showHTPNudge();
                this.shouldRestoreOnHTPClose = false;
            }
        }
    }

    private startReactivationTimeout(): void {
        if (this._minimumReactivationTimeMS > 0) {
            this._awaitingMinimumReactivationTimeout = true;
            window.clearTimeout(this._reactivationTimeout);
            this._reactivationTimeout = window.setTimeout(() => {
                this._awaitingMinimumReactivationTimeout = false;
                this.emit('reactivationTimerComplete');
            }, this._minimumReactivationTimeMS);
        }
    }

    protected startPostGameTimeout(): void {
        if (this._postGameTimeAmountDurationMS > 0) {
            const bigWinAmount: number = inversifyContainer.stake.currentStake * gameConfig.bigWinStakeMultiplier;
            const payout: number = inversifyContainer.gameModel.payout;

            if (this._preventAccidentalBuyIn || !this._postGameTimeoutWinOnly || (payout > 0 && payout < bigWinAmount)) {
                this._awaitingPostGameTimeout = true;
                window.clearTimeout(this._postGameTimout);
                this._postGameTimout = window.setTimeout(() => {
                    this._awaitingPostGameTimeout = false;

                    this.emit('postgameTimerComplete');
                }, this._postGameTimeAmountDurationMS);
            }
        }
    }

    private updateAutoPlayText(): void {
        const autoPlayStrings: IAutoPlayText = {
            changeStake: inversifyContainer.strings.overlays.autoplay.changeStake,
            cancel: inversifyContainer.strings.overlays.autoplay.cancel,
            confirm: inversifyContainer.strings.overlays.autoplay.confirm,
            maxLoss: this.getMaxLossText(),
            showFreePlay: false
        };

        this.setAutoPlayText(autoPlayStrings);
    }

    private getMaxLossText(): string {
        const maxPlays = this._maxAutoBuys;
        const maxLossValue = inversifyContainer.currencyFormatter.precise(inversifyContainer.stake.currentStake * maxPlays);

        return buildDynamicString(inversifyContainer.strings.overlays.autoplay.maxLoss, {
            autoplayCount: maxPlays,
            maxLoss: maxLossValue
        });
    }

    private isPurchaseError(error: unknown): error is IBaseServerResponse {
        return (error as IBaseServerResponse).ResultCode !== undefined;
    }

    protected setToBuyState(): void {
        if (this.inFreePlay) {
            this.updatePurchaseMainText(inversifyContainer.cabinetConfig.buttonTexts.freePlay);
            this.animateStakeText('');
        } else {
            this.updatePurchaseMainText(inversifyContainer.cabinetConfig.buttonTexts.buy);
            this.showPurchaseText();
            this.animateStakeText(inversifyContainer.stake.formattedStake);
        }
        this.holdSpinnerDuration = this._autoBuyPopupDelayS;

        const enableBuyState = () => {
            if (this._awaitingPostGameTimeout) {
                if (this._preventAccidentalBuyIn) {
                    this.enablePurchaseButtonInteractivity();
                }
                this.once('postgameTimerComplete', this.enablePurchaseButton, this);
            } else {
                this.enablePurchaseButton();
            }
        };

        if (this._awaitingMinimumReactivationTimeout) {
            this.once('reactivationTimerComplete', enableBuyState);
        } else {
            enableBuyState();
        }
    }

    private setActivePanelLog(): void {
        const companionState = useCompanionState();
        loggingModel.activePanel = companionState.activePanel.value;
    }
}
